import java.io.*;import java.nio.file.*;import java.util.*;public class ReportGenerator{static List<String>generate(List<Path>inputs,Path output)throws IOException{List<String>lines=new ArrayList<>();for(Path p:inputs){try(BufferedReader r=Files.newBufferedReader(p)){String line;while((line=r.readLine())!=null)lines.add(line);}catch(IOException e){System.err.println("Failed file: "+p+" : "+e.getMessage());}}try(BufferedWriter w=Files.newBufferedWriter(output)){for(String line:lines){w.write(line);w.newLine();}}return lines;}public static void main(String[]x)throws Exception{Path a=Files.createTempFile("store1",".txt"),b=Files.createTempFile("store2",".txt"),o=Files.createTempFile("summary",".txt");Files.write(a,Arrays.asList("Store A: 120","Store A: 90"));Files.write(b,Arrays.asList("Store B: 75"));System.out.println("Rows written: "+generate(Arrays.asList(a,b),o).size());Files.deleteIfExists(a);Files.deleteIfExists(b);Files.deleteIfExists(o);}}